package service
import("testing";"time";"ballast-watch/internal/model")
func TestBug21_WrappedAlertNotFoundCreatesAlert(t *testing.T){svc:=ballastTestServices(t);v:=mustVessel(t,svc);tank:=mustTank(t,svc,v);p:=mustPointBallast(t,svc,tank);_,err:=svc.Rules.Create(ballastCtx(),&model.ComplianceRuleInput{BallastTankID:tank.ID,Code:"SAL",ParamType:model.ParamHumidity,Op:model.OpGt,Threshold:80,DurationSec:1,Level:model.ComplianceAlertWarn,Enabled:true});if err!=nil{t.Fatal(err)};if err:=svc.Engine.Evaluate(ballastCtx(),[]*model.WaterReading{{SamplingPointID:p.ID,ParamType:model.ParamHumidity,Value:99,MeasuredAt:time.Now()}});err!=nil{t.Fatal(err)};alerts,err:=svc.ComplianceAlerts.List(ballastCtx(),model.ComplianceComplianceAlertInput{BallastTankID:tank.ID});if err!=nil||len(alerts)!=1{t.Fatalf("expected one alert: %d %v",len(alerts),err)}}
